<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../../../shared/api.js'
import {money} from '../../../shared/demo.mjs'
import Feedback from '../components/Feedback.vue'
import Pager from '../components/Pager.vue'
const data=ref({items:[],page:1,total:0}),error=ref(''),notice=ref(''),busy=ref(false),accounts=ref({})
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(page=1){data.value=await api(`/admin/withdrawals?page=${page}`)}
onMounted(()=>run(()=>load()))
async function reveal(item){await run(async()=>{accounts.value[item.id]=await api(`/admin/withdrawals/${item.id}/account`)})}
async function act(item,action){let body={};if(action==='reject'){const reason=prompt('请输入驳回原因');if(!reason?.trim())return;body={reason:reason.trim()}}else if(action==='paid'){const transferNote=prompt('请输入转账记录或流水号');if(!transferNote?.trim()||!confirm('确认已完成线下转账？'))return;body={transferNote:transferNote.trim()}}else if(!confirm('确认审核通过？'))return;await run(async()=>{await api(`/admin/withdrawals/${item.id}/${action}`,{method:'POST',body});await load(data.value.page);notice.value='操作成功'})}
async function upload(item,event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await run(async()=>{if(file.size>5*1024*1024)throw new Error('图片不能超过 5MB');const response=await fetch(`/api/admin/withdrawals/${item.id}/proof`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type},body:file});const result=await response.json();if(!response.ok)throw new Error(result.error?.message||'上传失败');await load(data.value.page);notice.value='凭证已上传'})}
</script>
<template><section class="panel"><Feedback :error="error" :notice="notice"/><h2>提现申请</h2><div v-for="item in data.items" :key="item.id" class="panel"><p><strong>{{ item.username }} · #{{ item.id }}</strong> · {{ {pending:'待审核',approved:'待线下转账',paid:'已转账',rejected:'已驳回'}[item.status] }}</p><p>申请 {{ money(item.amountUnits) }} 券 · 手续费 {{ money(item.feeUnits) }} 元 · 应转 {{ money(item.netUnits) }} 元</p><p>收款人 {{ item.accountName }} · 支付宝 {{ item.accountMasked }} · {{ item.createdAt }}</p><button class="table-button" :disabled="busy" @click="reveal(item)">查看收款账号</button><p v-if="accounts[item.id]">{{ accounts[item.id].accountName }} · {{ accounts[item.id].account }}</p><p v-if="item.reason">驳回原因：{{ item.reason }}</p><p v-if="item.transferNote">转账记录：{{ item.transferNote }}</p><a v-if="item.hasProof" :href="`/api/admin/withdrawals/${item.id}/proof`" target="_blank" rel="noopener">查看转账凭证</a><div v-if="item.status==='pending'"><button class="table-button" :disabled="busy" @click="act(item,'approve')">审核通过</button><button class="table-button" :disabled="busy" @click="act(item,'reject')">驳回并退券</button></div><div v-if="item.status==='approved'"><label>上传转账凭证 <input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="upload(item,$event)"></label><button class="table-button" :disabled="busy||!item.hasProof" @click="act(item,'paid')">确认已线下转账</button></div></div><p v-if="!data.items.length">暂无提现申请</p><Pager :page="data.page" :total="data.total" :disabled="busy" @change="page=>run(()=>load(page))"/></section></template>
